(()=>{const MATERIALS={"data/README.md":{"mime":"application/octet-stream","body":""},"data/actions_dry_run.csv":{"mime":"text/csv","body":""},"data/alerts_dry_run.csv":{"mime":"text/csv","body":""},"data/assignments.csv":{"mime":"text/csv","body":""},"data/distribution_batch_plan.csv":{"mime":"text/csv","body":""},"data/employees.csv":{"mime":"text/csv","body":""},"data/engagement_dashboard_mapping.csv":{"mime":"text/csv","body":""},"data/engagement_participants_buddy_poc.csv":{"mime":"text/csv","body":""},"data/engagement_participants_manager_poc.csv":{"mime":"text/csv","body":""},"data/engagement_participants_self_poc.csv":{"mime":"text/csv","body":""},"data/engagement_poc_assignments.csv":{"mime":"text/csv","body":""},"data/engagement_poc_expected_metrics.csv":{"mime":"text/csv","body":""},"data/engagement_poc_responses.csv":{"mime":"text/csv","body":""},"data/engagement_projects.csv":{"mime":"text/csv","body":""},"data/ex_participants_people.csv":{"mime":"text/csv","body":""},"data/lifecycle_schedule_plan.csv":{"mime":"text/csv","body":""},"data/manifest.json":{"mime":"application/json","body":""},"data/paired_gaps.csv":{"mime":"text/csv","body":""},"data/question_mapping.csv":{"mime":"text/csv","body":""},"data/relationships.csv":{"mime":"text/csv","body":""},"data/responses_buddy.csv":{"mime":"text/csv","body":""},"data/responses_index.csv":{"mime":"text/csv","body":""},"data/responses_manager.csv":{"mime":"text/csv","body":""},"data/responses_self.csv":{"mime":"text/csv","body":""},"data/scores_long.csv":{"mime":"text/csv","body":""},"data/simulated_ledger.csv":{"mime":"text/csv","body":""},"data/summary_means.csv":{"mime":"text/csv","body":""},"docs/操作教材.md":{"mime":"application/octet-stream","body":""},"docs/官方來源.md":{"mime":"application/octet-stream","body":""},"docs/帳號驗收表.csv":{"mime":"text/csv","body":""},"docs/學習地圖來源查核.json":{"mime":"application/json","body":""},"docs/Qualtrics_EX_零基礎學習地圖.docx":{"mime":"application/vnd.openxmlformats-officedocument.wordprocessingml.document","body":""},"docs/驗證報告.md":{"mime":"application/octet-stream","body":""},"docs/sources.json":{"mime":"application/json","body":""},"docs/官網重要文章參考指引/來源清單.json":{"mime":"application/json","body":""},"docs/官網重要文章參考指引/Qualtrics_EX_官方文章中文導讀與實作指引.docx":{"mime":"application/vnd.openxmlformats-officedocument.wordprocessingml.document","body":""},"surveys/README.md":{"mime":"application/octet-stream","body":""},"surveys/self_advanced.txt":{"mime":"text/plain","body":""},"surveys/manager_advanced.txt":{"mime":"text/plain","body":""},"surveys/buddy_advanced.txt":{"mime":"text/plain","body":""},"教學資源/進階文章導讀.md":{"mime":"application/octet-stream","body":""},"教學資源/技術對照與實戰練習.md":{"mime":"application/octet-stream","body":""},"教學資源/主管一次評多位新人.md":{"mime":"application/octet-stream","body":""},"教學資源/資源索引.json":{"mime":"application/json","body":""},"教學資源/bigquery_examples.sql":{"mime":"application/x-sql","body":""},"教學資源/驗算結果.json":{"mime":"application/json","body":""},"assets/official_S01.png":{"mime":"image/png","body":""},"assets/official_S05.png":{"mime":"image/png","body":""},"assets/official_S08.png":{"mime":"image/png","body":""},"assets/official_S09.png":{"mime":"image/png","body":""},"assets/official_S23.png":{"mime":"image/png","body":""},"assets/official_S26.png":{"mime":"image/png","body":""},"py_code/generate_data.py":{"mime":"text/x-python","body":""},"py_code/dashboard_lab.py":{"mime":"text/x-python","body":""},"README.md":{"mime":"application/octet-stream","body":""}};

document.addEventListener('click', event => {
  const link = event.target.closest('a[data-material]');
  if (!link) return;
  event.preventDefault();
  const key = link.dataset.material, item = MATERIALS[key];
  if (!item) return;
  const bytes = Uint8Array.from(atob(item.body), char => char.charCodeAt(0));
  const url = URL.createObjectURL(new Blob([bytes], {type: item.mime}));
  const a = document.createElement('a');
  a.href = url; a.download = key.split('/').pop(); document.body.append(a); a.click(); a.remove();
  document.getElementById('hub-status').textContent = '已準備下載：' + a.download;
  setTimeout(() => {URL.revokeObjectURL(url);document.getElementById('hub-status').textContent='';}, 4000);
});
})();
